mapper.select:
select b.SCHEME_DETAIL_ID schemeDetailId, b.SEC_TYPE secType, b.SEC_DETAIL_TYPE secDetailType, b.TRADE_MARKET tradeMarket, b.VALUATION_PRICE valuationPrice, b.VALUATION_PRICE_2 valuationPrice2, b.QUOTA_DIGIT quotaDigit, b.QUOTA_DEC_TYPE quotaDecType, b.PRICE_CLASS as priceClass, b.VALUATION_DATE valuationDate , b.VDATE vdate, b.MDATE mdate , b.CREATE_USER createUser, b.CREATE_DEPT createDept, b.CREATE_TIME createTime, b.UPDATE_USER updateUser, b.UPDATE_TIME updateTime from BOK_SHADOW_PRICE_DETAIL b left join BOK_SCHEME_INFO info on b.SCHEME_ID = info.SCH_ID
and b.SCHEME_ID = #{schId}
and b.SEC_TYPE = #{secType}
and b.TRADE_MARKET = #{tradeMarket}
and b.SEC_DETAIL_TYPE = #{secDetailType}
and b.VDATE =STR_TO_DATE(#{vdate}, '%Y-%m-%d')

select
    b.*
    from BOK_SHADOW_PRICE_DETAIL b
        left join BOK_SCHEME_INFO info
    on b.SCHEME_ID = info.SCH_ID
    WHERE b.SCHEME_ID = #{schemeId}
          and  b.SEC_TYPE = #{secType}
          and  b.TRADE_MARKET = #{tradeMarket}
          and  b.SEC_DETAIL_TYPE = #{secDetailType}
          and  b.VDATE =STR_TO_DATE(#{vdate}, '%Y-%m-%d')
